import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// CLOUDAKE (felps) — anúncio de ~34 s: "Todos os aplicativos que você precisa. Uma única assinatura."
// Identidade do logo e das telas: azul-marinho quase preto, azul elétrico → ciano, letra geométrica pesada, cada app com a sua cor.
// Problema (0–11 s) só com cartões genéricos desenhados; a Cloudake (logo, ícones, telas) só entra quando a fala apresenta a solução.
// Nenhuma marca de terceiro: a tela de vídeo do cliente diz "Vegas" e é recortada abaixo da barra de título (vira "Cloudake Video").
// Locução o locutor sem pausas (public/felps/voz-v1.wav, tools/felps_sem_pausas.py), entra em VO s.

const { fontFamily: POP } = loadPoppins("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const CK_FPS = 30;
const VO = 0.15;
export const CK_FRAMES = 37 * CK_FPS; // v2: +3 s para "Teste grátis por 3 dias" (pedido do cliente, 20/10)
const BG = "#010822";
const NAVY = "#071233";
const CARD = "#0D1A3F";
const EDGE = "#22346A";
const BLUE = "#1E6BFF";
const CYAN = "#29C8FF";
const WHITE = "#FFFFFF";
const MUTED = "#8C9BC4";
const CORAL = "#FF5A72";
const asset = (f: string) => staticFile(`felps/${f}`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const IN = Easing.bezier(0.55, 0, 1, 0.45);
const BACK = Easing.out(Easing.back(1.7));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const ein = (t: number, a: number, d = 0.3) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
const pop = (t: number, a: number, d = 0.42) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: number) => s + VO; // tempo da fala → tempo do vídeo
const bump = (t: number, at: number, amt = 0.05, d = 0.35) => (t >= at ? amt * (1 - k(t, at, d)) : 0);
const shake = (t: number, at: number, amp = 9, d = 0.3): [number, number] =>
  t > at && t < at + d ? [Math.sin(t * 91) * amp * (1 - (t - at) / d), Math.cos(t * 77) * amp * (1 - (t - at) / d)] : [0, 0];

// ───────── cenas pelo tempo do vídeo ─────────
const S = {
  hook: 0,
  prob: v(2.97),
  junta: v(8.36),
  logo: v(11.02),
  nav: v(12.72),
  photo: v(16.1),
  draw: v(18.26),
  video: v(20.44),
  mais: v(22.71),
  semInstalar: v(26.39),
  todos: v(27.95),
  uma: v(29.96),
  fim: v(31.45),
};

// ───────── peças comuns ─────────
const Back: React.FC<{ t: number; hue?: string }> = ({ t, hue = BLUE }) => (
  <AbsoluteFill style={{ background: BG }}>
    <AbsoluteFill style={{ background: `radial-gradient(60% 38% at 50% ${48 + Math.sin(t * 0.6) * 2}%, ${hue}26 0%, ${hue}00 70%)` }} />
  </AbsoluteFill>
);
const Cam: React.FC<{ s?: number; x?: number; y?: number; r?: number; children: React.ReactNode }> = ({ s = 1, x = 0, y = 0, r = 0, children }) => (
  <AbsoluteFill style={{ transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) scale(${s.toFixed(4)}) rotate(${r.toFixed(3)}deg)` }}>{children}</AbsoluteFill>
);
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);

// texto cinético: cada palavra bate no tempo dela (tempo da fala) e depois fica parada
type W = [string, number, string?];
const K: React.FC<{ t: number; words: W[]; size: number; color?: string; weight?: number; out?: number }> = ({ t, words, size, color = WHITE, weight = 800, out }) => {
  const gone = out !== undefined ? ein(t, out, 0.16) : 0;
  return (
    <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "baseline", columnGap: size * 0.26, rowGap: 0, fontFamily: POP, fontWeight: weight, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.02em", color, textAlign: "center", opacity: 1 - gone, transform: `scale(${1 - gone * 0.08})` }}>
      {words.map(([w, at, c], i) => {
        if (w === "|") return <div key={i} style={{ flexBasis: "100%", height: 0 }} />; // quebra de linha fixa
        const a = v(at) - 0.05;
        const e = k(t, a, 0.26);
        return (
          <span key={i} style={{ display: "inline-block", whiteSpace: "nowrap", opacity: k(t, a, 0.08), transform: `translateY(${((1 - e) * size * 0.35).toFixed(1)}px) scale(${(1 + (1 - e) * 0.35).toFixed(3)})`, color: c, textShadow: c === CYAN || c === BLUE ? `0 0 22px ${c}66` : "0 6px 18px rgba(0,0,0,0.45)" }}>
            {w}
          </span>
        );
      })}
    </div>
  );
};
// frases que se revezam no MESMO lugar: a anterior some inteira antes de a próxima entrar
const Rev: React.FC<{ t: number; size: number; lines: { words: W[]; until?: number }[] }> = ({ t, size, lines }) => (
  <div style={{ position: "relative", width: "100%", display: "grid" }}>
    {lines.map((l, i) => {
      const start = v(l.words[0][1]) - 0.06;
      const end = l.until ?? Infinity;
      if (t < start - 0.01 || t > end + 0.01) return null;
      return (
        <div key={i} style={{ gridArea: "1 / 1" }}>
          <K t={t} words={l.words} size={size} out={end === Infinity ? undefined : end - 0.16} />
        </div>
      );
    })}
  </div>
);
const Cursor: React.FC<{ x: number; y: number; s?: number; press?: number }> = ({ x, y, s = 1, press = 0 }) => (
  <svg width={60 * s} height={74 * s} viewBox="0 0 22 27" style={{ position: "absolute", left: x, top: y, filter: "drop-shadow(0 8px 10px rgba(0,0,0,0.6))", zIndex: 20, transform: `scale(${1 - press * 0.14})`, transformOrigin: "10% 10%" }}>
    <path d="M2 2 L2 21 L7 16.5 L10.5 24.5 L14 23 L10.5 15 L17.5 15 Z" fill={WHITE} stroke="#000" strokeWidth={1.4} strokeLinejoin="round" />
  </svg>
);
const Ripple: React.FC<{ t: number; at: number; x: number; y: number; c?: string }> = ({ t, at, x, y, c = CYAN }) => {
  if (t < at || t > at + 0.55) return null;
  const p = k(t, at, 0.55);
  return <div style={{ position: "absolute", left: x - 90 * p, top: y - 90 * p, width: 180 * p, height: 180 * p, borderRadius: "50%", border: `6px solid ${c}`, opacity: 1 - p, zIndex: 19 }} />;
};
// ícone oficial de um app (recortado do PNG que o cliente mandou)
const App: React.FC<{ id: string; size: number; style?: React.CSSProperties }> = ({ id, size, style }) => (
  <Img src={asset(`app-${id}.png`)} style={{ width: size, height: size, display: "block", ...style }} />
);
type AppInfo = { id: string; name: string; c: string };
const APPS: AppInfo[] = [
  { id: "photo", name: "Photo", c: "#2F8BFF" },
  { id: "draw", name: "Draw", c: "#21D47E" },
  { id: "video", name: "Video", c: "#9B5CFF" },
  { id: "design", name: "Design", c: "#FF4FA3" },
  { id: "docs", name: "Docs", c: "#2F8BFF" },
  { id: "sheets", name: "Sheets", c: "#21D47E" },
  { id: "slides", name: "Slides", c: "#FF8A1E" },
  { id: "pdf", name: "PDF", c: "#FF3B4A" },
  { id: "audio", name: "Audio", c: "#2BD68F" },
  { id: "effects", name: "Effects", c: "#A66BFF" },
  { id: "light", name: "Light", c: "#33B6FF" },
  { id: "ui", name: "UI", c: "#B55CFF" },
  { id: "cad", name: "CAD", c: "#FF3B4A" },
];
const AppName: React.FC<{ name: string; c: string; size: number }> = ({ name, c, size }) => (
  <div style={{ fontFamily: POP, fontWeight: 700, fontSize: size, letterSpacing: "-0.02em", whiteSpace: "nowrap", color: WHITE }}>
    Cloud<span style={{ color: CYAN }}>ake</span> <span style={{ color: c }}>{name}</span>
  </div>
);

// recorte de uma tela do cliente (1600×900): mostra a região [x, y, w] (altura = w / 1.6) num quadro de largura W
const Screen: React.FC<{ src: string; x: number; y: number; w: number; W: number; glow: string }> = ({ src, x, y, w, W, glow }) => {
  const sc = W / w;
  return (
    <div style={{ position: "relative", width: W, height: W / 1.6, borderRadius: 28, overflow: "hidden", border: `2px solid ${glow}88`, boxShadow: `0 30px 80px rgba(0,0,0,0.6), 0 0 50px ${glow}40` }}>
      <Img src={asset(src)} style={{ position: "absolute", width: 1600 * sc, height: 900 * sc, left: -x * sc, top: -y * sc, maxWidth: "none" }} />
    </div>
  );
};

// ───────── ícones genéricos (cena do problema, sem marca nenhuma) ─────────
const Line: React.FC<{ kind: "foto" | "video" | "design" | "doc"; s: number }> = ({ kind, s }) => {
  const p = { fill: "none", stroke: WHITE, strokeWidth: 5, strokeLinecap: "round", strokeLinejoin: "round" } as const;
  return (
    <svg width={s} height={s} viewBox="0 0 100 100">
      {kind === "foto" ? (
        <>
          <rect x={12} y={28} width={76} height={54} rx={10} {...p} />
          <path d="M34 28 L40 18 H60 L66 28" {...p} />
          <circle cx={50} cy={55} r={15} {...p} />
        </>
      ) : kind === "video" ? (
        <>
          <rect x={12} y={24} width={76} height={54} rx={10} {...p} />
          <path d="M43 39 L60 51 L43 63 Z" {...p} />
          <path d="M12 86 H88" {...p} />
        </>
      ) : kind === "design" ? (
        <>
          <circle cx={34} cy={36} r={16} {...p} />
          <rect x={52} y={22} width={30} height={30} rx={5} {...p} />
          <path d="M22 82 L40 56 L58 82 Z" {...p} />
          <path d="M64 64 L84 84" {...p} />
        </>
      ) : (
        <>
          <path d="M26 12 H60 L76 28 V88 H26 Z" {...p} />
          <path d="M60 12 V28 H76" {...p} />
          <path d="M38 48 H64 M38 60 H64 M38 72 H54" {...p} />
        </>
      )}
    </svg>
  );
};
const Bill: React.FC<{ label: string; kind: "foto" | "video" | "design" | "doc"; w: number }> = ({ label, kind, w }) => (
  <div style={{ width: w, height: w * 1.06, borderRadius: 34, background: CARD, border: `2px solid ${EDGE}`, boxShadow: "0 24px 60px rgba(0,0,0,0.55)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: w * 0.05 }}>
    <Line kind={kind} s={w * 0.4} />
    <div style={{ fontFamily: POP, fontWeight: 700, fontSize: w * 0.12, color: WHITE }}>{label}</div>
    <div style={{ fontFamily: POP, fontWeight: 700, fontSize: w * 0.07, color: CORAL, background: `${CORAL}22`, border: `2px solid ${CORAL}88`, padding: `${w * 0.015}px ${w * 0.05}px`, borderRadius: 999, letterSpacing: "0.04em" }}>+1 ASSINATURA</div>
  </div>
);
// cobrança genérica que cai na pilha da abertura
const Charge: React.FC<{ w: number; i: number }> = ({ w, i }) => (
  <div style={{ width: w, height: 150, borderRadius: 28, background: CARD, border: `2px solid ${EDGE}`, boxShadow: "0 20px 50px rgba(0,0,0,0.55)", display: "flex", alignItems: "center", gap: 28, padding: "0 34px", boxSizing: "border-box" }}>
    <div style={{ width: 84, height: 84, borderRadius: 22, background: `${CORAL}22`, border: `2px solid ${CORAL}88`, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <svg width={48} height={48} viewBox="0 0 24 24">
        <rect x={2.5} y={5} width={19} height={14} rx={2.5} fill="none" stroke={CORAL} strokeWidth={2} />
        <path d="M2.5 9.5 H21.5" stroke={CORAL} strokeWidth={2} />
      </svg>
    </div>
    <div style={{ display: "flex", flexDirection: "column", gap: 10, flex: 1 }}>
      <div style={{ fontFamily: POP, fontWeight: 700, fontSize: 40, color: WHITE }}>Assinatura {i + 1}</div>
      <div style={{ height: 14, width: `${70 - i * 7}%`, borderRadius: 8, background: EDGE }} />
    </div>
    <div style={{ fontFamily: POP, fontWeight: 700, fontSize: 30, color: CORAL, letterSpacing: "0.03em" }}>COBRADA</div>
  </div>
);

// ───────── 1 · abertura: cobranças caindo em pilha, uma por batida ─────────
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const hits = [0.05, 0.41, 1.03, 1.63, 2.17].map(v);
  const sh = hits.reduce<[number, number]>((a, h) => { const s = shake(t, h + 0.18, 8); return [a[0] + s[0], a[1] + s[1]]; }, [0, 0]);
  const zoom = 1.04 + lin(t, 0, S.prob) * 0.08 + hits.reduce((a, h) => a + bump(t, h + 0.18, 0.025), 0);
  return (
    <Cam s={zoom} x={sh[0]} y={sh[1]}>
      <Col top={360}>
        <Rev t={t} size={104} lines={[
          { words: [["QUANTAS", 0.05], ["ASSINATURAS", 0.41, CYAN]], until: v(0.98) },
          { words: [["VOCÊ", 1.03], ["PAGA", 1.33], ["PRA", 1.63], ["TRABALHAR?", 2.17, CYAN]] },
        ]} />
      </Col>
      {hits.map((h, i) => {
        const p = k(t, h, 0.32);
        const y = mix(-500, 0, p);
        const r = [-4, 3, -2, 5, -3][i];
        return (
          <div key={i} style={{ position: "absolute", left: 140, top: 780 + i * 130 + y, opacity: k(t, h, 0.06), transform: `rotate(${(r * (1.6 - p * 0.6)).toFixed(2)}deg) scale(${(1.25 - p * 0.25).toFixed(3)})`, zIndex: i }}>
            <Charge w={800} i={i} />
          </div>
        );
      })}
    </Cam>
  );
};

// ───────── 2 e 3 · uma pra foto, outra pra vídeo… e tudo se junta num lugar só ─────────
const ITEMS: { label: string; kind: "foto" | "video" | "design" | "doc"; at: number }[] = [
  { label: "Foto", kind: "foto", at: 3.29 },
  { label: "Vídeo", kind: "video", at: 4.87 },
  { label: "Design", kind: "design", at: 5.83 },
  { label: "Documentos", kind: "doc", at: 7.5 },
];
const Problema: React.FC<{ t: number }> = ({ t }) => {
  const enter = k(t, S.prob - 0.05, 0.35);
  const gather = io(t, v(8.74), 0.75); // "tudo isso" → os cartões correm para o centro
  const focus = ITEMS.reduce((a, it, i) => (t >= v(it.at) - 0.1 ? i : a), 0);
  const slot = (i: number) => [i % 2 === 0 ? -215 : 215, i < 2 ? -235 : 235];
  const [fx, fy] = slot(focus);
  const camX = mix(-fx * 0.12, 0, gather);
  const camY = mix(-fy * 0.1, 0, gather);
  const cloud = pop(t, v(9.3), 0.5); // os cartões somem dentro da nuvem; ela bate de novo em "lugar só"
  const sh = shake(t, v(9.98), 10);
  return (
    <Cam s={mix(0.94, 1, enter) + ITEMS.reduce((a, it) => a + bump(t, v(it.at), 0.03), 0)} x={camX + sh[0]} y={camY + sh[1]}>
      <Col top={300}>
        <Rev t={t} size={92} lines={[
          { words: [["UMA", 2.97], ["PRA", 3.19], ["FOTO", 3.67, CYAN]], until: v(4.36) },
          { words: [["OUTRA", 4.41], ["PRA", 4.65], ["VÍDEO", 4.87, CYAN]], until: v(5.42) },
          { words: [["OUTRA", 5.47], ["PRA", 5.71], ["DESIGN", 5.83, CYAN]], until: v(6.68) },
          { words: [["E", 6.74], ["MAIS", 6.82], ["UMA", 7.14], ["PROS", 7.32], ["DOCUMENTOS", 7.5, CYAN]], until: v(8.3) },
          { words: [["E", 8.36], ["SE", 8.48], ["TUDO", 8.74], ["ISSO", 9.08]], until: v(9.28) },
          { words: [["ESTIVESSE", 9.32], ["NUM", 9.84], ["LUGAR", 9.98, CYAN], ["SÓ?", 10.46, CYAN]] },
        ]} />
      </Col>
      {ITEMS.map((it, i) => {
        const [x, y] = slot(i);
        const a = v(it.at) - 0.12;
        const p = pop(t, a, 0.4);
        const s = mix(0, 1, p) * mix(1, 0.15, gather);
        const dim = i < focus && gather === 0 ? 0.55 : 1;
        return (
          <div key={i} style={{ position: "absolute", left: 540 + x * (1 - gather) - 200, top: 1130 + y * (1 - gather) - 212, opacity: (t >= a ? 1 : 0) * (1 - lin(t, v(9.3), v(9.5))) * dim, transform: `scale(${s.toFixed(3)}) rotate(${((1 - p) * (i % 2 ? 12 : -12) + gather * (i % 2 ? 90 : -90)).toFixed(1)}deg)` }}>
            <Bill label={it.label} kind={it.kind} w={400} />
          </div>
        );
      })}
      {t > v(9.28) ? (
        <div style={{ position: "absolute", left: 540 - 230, top: 1130 - 230, width: 460, height: 460, transform: `scale(${(cloud * (1 + bump(t, v(9.98), 0.12, 0.4))).toFixed(3)})`, opacity: k(t, v(9.3), 0.1) }}>
          <Img src={asset("logo-simbolo-alpha.png")} style={{ width: 460, height: 460, filter: `drop-shadow(0 0 40px ${BLUE})` }} />
        </div>
      ) : null}
    </Cam>
  );
};

// ───────── 4 · "Essa é a Cloudake": logo grande com clarão ─────────
const Logo: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const p = k(t, at, 0.5);
  const flash = 1 - k(t, at, 0.4);
  return (
    <Cam s={mix(1.25, 1, p) + lin(t, at, at + 2) * 0.05}>
      <AbsoluteFill style={{ background: `radial-gradient(50% 30% at 50% 50%, ${BLUE}55 0%, ${BLUE}00 70%)`, opacity: p }} />
      <div style={{ position: "absolute", left: 90, top: 960 - 225, width: 900, height: 225, opacity: k(t, at, 0.12) }}>
        <Img src={asset("logo-completo-alpha.png")} style={{ width: 900, height: 225 }} />
      </div>
      <Col top={1260}>
        <K t={t} words={[["Todos", at - VO + 0.35], ["os", at - VO + 0.42], ["apps", at - VO + 0.49, CYAN], ["num", at - VO + 0.56], ["lugar", at - VO + 0.63], ["só", at - VO + 0.7, CYAN]]} size={58} weight={600} />
      </Col>
      <AbsoluteFill style={{ background: WHITE, opacity: flash * 0.55 }} />
    </Cam>
  );
};

// ───────── 5 · navegador com os 13 apps; o cursor escolhe o Photo ─────────
const Navegador: React.FC<{ t: number }> = ({ t }) => {
  const a = S.nav;
  const enter = k(t, a, 0.5);
  const clickAt = v(14.6);
  const zoomAt = v(15.3);
  const z = io(t, zoomAt, 0.62);
  const W = 920, H = 1060, L = 80, T = 600;
  const cols = 4, cell = 205;
  const gx = (i: number) => L + 50 + (i % cols) * cell + (cell - 150) / 2 + (i >= 12 ? cell * 1.5 : 0);
  const gy = (i: number) => T + 150 + Math.floor(i / cols) * 230;
  // posição do ícone do Photo (índice 0) para o cursor e para o zoom
  const px = gx(0) + 75, py = gy(0) + 75;
  const cx = mix(980, px + 10, io(t, v(13.95), 0.6));
  const cy = mix(1700, py + 18, io(t, v(13.95), 0.6));
  const press = t > clickAt && t < clickAt + 0.18 ? 1 : 0;
  const s = mix(1, 4, z);
  return (
    <Cam s={mix(0.9, 1, enter) + lin(t, a, zoomAt) * 0.04} y={mix(140, 0, enter)}>
      <div style={{ position: "absolute", inset: 0, transformOrigin: `${px}px ${py}px`, transform: `scale(${s.toFixed(3)})`, opacity: 1 - lin(t, zoomAt + 0.3, zoomAt + 0.55) }}>
        <Col top={310}>
          <Rev t={t} size={88} lines={[
            { words: [["ABRE", 12.98], ["O", 13.12], ["NAVEGADOR", 13.16, CYAN]], until: v(13.88) },
            { words: [["ESCOLHE", 13.92], ["O", 14.24], ["APP", 14.28, CYAN]], until: v(15.1) },
            { words: [["E", 15.16], ["COMEÇA", 15.24], ["A", 15.6], ["CRIAR", 15.66, CYAN]] },
          ]} />
        </Col>
        <div style={{ position: "absolute", left: L, top: T, width: W, height: H, borderRadius: 40, background: NAVY, border: `2px solid ${EDGE}`, boxShadow: `0 40px 100px rgba(0,0,0,0.6), 0 0 60px ${BLUE}30`, opacity: enter, overflow: "hidden" }}>
          <div style={{ height: 96, display: "flex", alignItems: "center", gap: 16, padding: "0 34px", borderBottom: `2px solid ${EDGE}`, background: "#0A1640" }}>
            {["#FF5F57", "#FEBC2E", "#28C840"].map((c) => <div key={c} style={{ width: 22, height: 22, borderRadius: 11, background: c }} />)}
            <div style={{ marginLeft: 24, flex: 1, height: 52, borderRadius: 26, background: BG, border: `2px solid ${EDGE}`, display: "flex", alignItems: "center", padding: "0 26px", gap: 14 }}>
              <svg width={26} height={26} viewBox="0 0 24 24"><rect x={5} y={10} width={14} height={11} rx={2} fill={MUTED} /><path d="M8 10 V7 a4 4 0 0 1 8 0 V10" stroke={MUTED} strokeWidth={2.4} fill="none" /></svg>
              <div style={{ fontFamily: POP, fontWeight: 600, fontSize: 30, color: WHITE }}>
                cloud<span style={{ color: CYAN }}>ake</span>
              </div>
            </div>
